import "core-js/modules/es.array.push.js";
import SnackBar from "@/components/SnackBar.vue";
import CreatetvBoard from "@/components/TvApp/Popups/CreatetvBoard.vue";
import TvboardLibrary from "@/components/TvApp/TvboardLibrary.vue";
import TvboardList from "@/components/TvApp/TvboardList.vue";
export default {
  components: {
    TvboardList,
    TvboardLibrary,
    CreatetvBoard,
    SnackBar
  },
  data: () => ({
    toggle_exclusive: null,
    componentCheck: 0,
    tvboardCreation: false,
    subcribedKey: 0,
    SnackBarComponent: {}
  }),
  created() {
    this.toggle_exclusive = this.$store.getters.Gettvboardback == false ? "orgtvboard" : "tv_library";
  },
  methods: {
    back_call() {
      this.$router.push("/AdminLevelApps");
    },
    add_tvchannel() {
      this.componentCheck = 1;
      this.tvboardCreation = true;
    },
    subcribedrefesh() {
      this.subcribedKey += 1;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.tvboardCreation = false;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    }
  }
};
